package com.meshcrossway.android;

import java.util.*;
import java.nio.charset.StandardCharsets;
import static com.meshcrossway.android.MeshData.*;
import static com.meshcrossway.android.McIntegrationTest.*;

/** User-facing MeshCore onboarding, channel round trips, diagnostic privacy and contact state. */
public final class McFeaturesTest {
    static int assertions;
    static void verify(boolean ok,String message){assertions++;if(!ok)throw new AssertionError(message);}
    static void bad(Runnable action,String message){boolean rejected=false;try{action.run();}catch(IllegalArgumentException e){rejected=true;}verify(rejected,message);}
    static byte[] channel(int slot,String name,byte[] key){byte[] f=new byte[50];f[0]=18;f[1]=(byte)slot;byte[] text=name.getBytes(StandardCharsets.UTF_8);System.arraycopy(text,0,f,2,text.length);System.arraycopy(key,0,f,34,16);return f;}
    static void readback(ProtocolClient c,byte[] frame){int reads=0;while(c.mcAdmin.edit!=null){if(++reads>4)throw new AssertionError("Unbounded channel verification");ProtocolClient.Command q=take(c);verify(q.mcVerification,"Channel confirmation must not replay a SET");if(q.data[0]==31)receive(c,frame);else if(q.data[0]==1)receive(c,self(22,30,0,"Audit"));else throw new AssertionError("Unexpected channel readback opcode");}c.next(clock++);}
    static void links(){
        McChannelLink shared=new McChannelLink("Équipe + 1",McChannelLink.secret(McChannelLink.PUBLIC_KEY),"#front range");McChannelLink parsed=McChannelLink.parse(shared.link());
        verify(parsed.name.equals(shared.name)&&parsed.scope.equals(shared.scope)&&Arrays.equals(parsed.secret,shared.secret),"Official URI round trip preserves Unicode, plus sign, scope and key");
        bad(()->shared.requireScope(false,true,shared.scope),"Scoped import needs supported firmware");bad(()->shared.requireScope(true,false,shared.scope),"Scoped import waits for loaded region");bad(()->shared.requireScope(true,true,"#other"),"Scoped import never silently changes regions");shared.requireScope(true,true,shared.scope);verify(true,"Matching configured scope is accepted");new McChannelLink("Unscoped",shared.secret,"").requireScope(false,false,"#other");verify(true,"Unscoped import does not change the radio default");
        verify(McChannelLink.parse("meshcore://channel/add?name=Public&secret="+McChannelLink.PUBLIC_KEY).name.equals("Public"),"Official documented Public channel link imports");
        verify(Wire.hex(McChannelLink.hashtag("#test").secret).equals("9cd8fcf22a47333b591d96a2b848b73f"),"Hashtag key matches pinned official SHA256 vector");
        McChannelLink first=McChannelLink.privateChannel("Private"),second=McChannelLink.privateChannel("Private");verify(first.secret.length==16&&!Arrays.equals(first.secret,second.secret),"Private channels receive independent random keys");
        byte[] input=first.secret.clone();McChannelLink copied=new McChannelLink("Private",input,"");input[0]^=1;verify(!Arrays.equals(input,copied.secret),"Link owns a copy of supplied key material");
        String base="meshcore://channel/add?name=Public&secret="+McChannelLink.PUBLIC_KEY;
        for(String value:new String[]{base+"&name=Other",base+"&secret="+McChannelLink.PUBLIC_KEY,base+"&unknown=1",base+"#fragment",base.replace("meshcore://","https://"),base.replace("channel/add","channel/other"),base.replace(McChannelLink.PUBLIC_KEY,"00"),base.replace(McChannelLink.PUBLIC_KEY,"00".repeat(16)),base.replace("name=Public","name="),base.replace("name=Public","name=%00"),base.replace("name=Public","name=%FF"),base.replace("channel/add","user@channel/add"),base.replace("channel/add","channel:42/add")})bad(()->McChannelLink.parse(value),"Malformed or unsupported URI rejected without guessing");
        bad(()->new McChannelLink("é".repeat(16),first.secret,""),"Channel UTF8 name must fit 31 bytes");bad(()->McChannelLink.hashtag("test"),"Hashtag is explicit");bad(()->new McChannelLink(" Private",first.secret,""),"Whitespace is not silently normalized inside protocol helper");bad(()->new McChannelLink("Two\nlines",first.secret,""),"Control characters are not valid channel names");
    }
    static void channels(){
        ProtocolClient c=fresh();Channel old=c.channels.get(0);byte[] key=new byte[16];Arrays.fill(key,(byte)2);c.setMcChannel(0,"New group",key);verify(c.channels.get(0)==old,"Channel model stays unchanged before confirmation");ProtocolClient.Command q=take(c);
        verify(q.data.length==50&&q.data[0]==32&&q.data[1]==0&&Arrays.equals(key,Arrays.copyOfRange(q.data,34,50)),"SET_CHANNEL uses official 50-byte frame and 16-byte key");ack(c);verify(c.mcAdmin.edit!=null,"Radio ACK alone does not confirm channel write");
        byte[] returned=channel(0,"New group",key);Arrays.fill(returned,12,34,(byte)0x5a);returned[11]=0;readback(c,returned);verify(c.mcAdmin.error.isEmpty()&&c.channels.get(0).name.equals("New group"),"Readback ignores unused bytes after the name terminator");verify(c.ready&&c.nextChannel==1,"Readback does not restart bootstrap/channel iteration");
        final ProtocolClient changed=c;final Channel previous=old;bad(()->changed.send(Target.channel(previous),"old key",1,clock),"Old conversation target cannot send with a replaced channel key");
        c=fresh();old=c.channels.get(0);byte[] original=c.channelKeys.get(0).clone();c.setMcChannel(0,"Renamed",original);take(c);ack(c);readback(c,channel(0,"Renamed",original));verify(c.channels.get(0).identity.equals(old.identity),"Renaming retains key identity and history topic");
        c=fresh();c.setMcChannel(0,"Expected",key);take(c);ack(c);readback(c,channel(0,"Different",key));verify(c.mcAdmin.error.contains("Channel")&&c.channels.get(0).name.equals("Different"),"Mismatched readback shows actual channel values");
        c=fresh();c.setMcChannel(0,"Same name",key);take(c);ack(c);byte[] otherKey=key.clone();otherKey[0]^=1;readback(c,channel(0,"Same name",otherKey));verify(c.mcAdmin.error.contains("Channel")&&Arrays.equals(c.channelKeys.get(0),otherKey),"Key mismatch cannot be reported as a confirmed save");
        c=fresh();c.setMcChannel(0,"Rejected",key);take(c);receive(c,new byte[]{1,6});verify(c.ready&&c.channels.get(0).name.equals("Test")&&!c.mcAdmin.error.isEmpty(),"Ordinary channel rejection keeps connection and confirmed model");
        c=fresh();old=c.channels.get(0);c.setMcChannel(0,"",new byte[16]);q=take(c);verify(q.data[0]==32&&Arrays.equals(Arrays.copyOfRange(q.data,2,50),new byte[48]),"Channel removal clears both name and key");ack(c);readback(c,channel(0,"",new byte[16]));verify(!c.channels.get(0).enabled,"Removed channel is disabled only after readback");final ProtocolClient removed=c;final Channel retired=old;bad(()->removed.send(Target.channel(retired),"removed",2,clock),"Removed channel cannot send");
        ProtocolClient limits=fresh();bad(()->limits.setMcChannel(1,"Bad slot",key),"Out-of-range slot cannot be written");bad(()->limits.setMcChannel(0,"Active",new byte[16]),"All-zero active key is rejected");bad(()->limits.setMcChannel(0,"",key),"Deletion requires both fields empty");bad(()->limits.setMcChannel(0,"é".repeat(16),key),"32-byte channel name cannot be truncated by firmware");
        ProtocolClient duplicate=fresh();duplicate.channelCount=2;Channel occupied=new Channel();occupied.slot=1;occupied.enabled=true;occupied.name="Occupied";duplicate.channels.put(1,occupied);duplicate.channelKeys.put(1,key.clone());bad(()->duplicate.setMcChannel(0,"Duplicate",key),"Duplicate active keys cannot create ambiguous channel slots");
        c=fresh();final ProtocolClient unloaded=c;bad(()->unloaded.shareMcChannel(0),"Sharing waits for scope metadata");take(c);receive(c,new byte[]{28});c.next(clock++);McChannelLink share=McChannelLink.parse(c.shareMcChannel(0));verify(share.name.equals("Test")&&Arrays.equals(share.secret,c.channelKeys.get(0)),"Sharing exports only confirmed radio channel key");
        c=fresh();c.channelCount=40;c.refreshMcChannels();boolean bounded=true;for(int i=0;i<40;i++){ProtocolClient.Command next=take(c);bounded&=c.commands.size()<8&&next.data[0]==31&&(next.data[1]&255)==i;receive(c,channel(i,"",new byte[16]));}c.next(clock++);verify(bounded&&c.mcDeferredChannels.isEmpty(),"Refreshing many slots is bounded and serialized");verify(c.ready&&c.nextChannel==1,"Refreshing channel slots never re-enters bootstrap");
        c=fresh();c.setMcChannel(0,"Recovered",key);q=c.next(clock++);c.writeAccepted(q.data);McAdmin.Edit pending=c.pendingMcSave();ProtocolClient restored=fresh();restored.mcAdmin.restore(pending);restored.mcAdmin.ready();readback(restored,channel(0,"Recovered",key));verify(restored.mcAdmin.error.isEmpty(),"Channel change recovers after disconnect with GET only");
    }
    static void announcements(){
        ProtocolClient c=fresh();c.announceSelf(false);verify(c.mcAdvertPending&&c.mcAdvertStatus.contains("queued"),"Explicit announcement exposes pending state");ProtocolClient.Command q=take(c);verify(Arrays.equals(q.data,new byte[]{7,0}),"Nearby announcement requests zero-hop advert");final ProtocolClient pending=c;bad(()->pending.announceSelf(true),"Repeated taps cannot queue duplicate announcements");ack(c);c.next(clock++);verify(!c.mcAdvertPending&&c.mcAdvertStatus.contains("not confirmed"),"Accepted announcement does not claim remote reception");bad(()->pending.announceSelf(true),"Announcements have a 30-second cooldown");c.mcAdmin.tick(clock+=30001);c.announceSelf(true);q=take(c);verify(Arrays.equals(q.data,new byte[]{7,1}),"Mesh-wide announcement requests a flood advert");receive(c,new byte[]{1,6});c.next(clock++);verify(c.ready&&!c.mcAdvertPending&&c.mcAdvertStatus.contains("rejected"),"Announcement error stays local and clears pending state");
        c=fresh();c.setName("Pending");final ProtocolClient busy=c;bad(()->busy.announceSelf(false),"Announcement waits for unresolved identity/settings changes");verify(c.commands.stream().noneMatch(v->v.data[0]==7),"No automatic announcement is inserted into a settings save");
        ProtocolClient offline=new ProtocolClient(RadioProfile.MESHCORE,42,new Events());bad(()->offline.announceSelf(true),"Offline announcement is rejected");
    }
    static void contacts(){
        ProtocolClient c=fresh();Node n=c.nodes.values().iterator().next();verify(McContacts.state(n,c)==ProtocolClient.MC_APPROVED,"Current membership has Approved state");Node absent=new Node(n);absent.id="09"+"00".repeat(31);verify(McContacts.state(absent,c)==ProtocolClient.MC_RETIRED,"Old saved approval is historical when absent after synchronization");receive(c,contact(138,8));Node discovered=c.mcDiscoveries.values().iterator().next();verify(McContacts.state(discovered,c)==ProtocolClient.MC_DISCOVERED,"New discovery has a separate state");verify(McContacts.label(n,null).contains("last saved"),"Offline state does not claim current radio membership");Node unknown=new Node();verify(McContacts.state(unknown,null)==ProtocolClient.MC_RETIRED,"Legacy unclassified entries do not become approved");verify(McContacts.label(absent,c).contains("Historical"),"Historical state is explained explicitly");
    }
    static void diagnostic(){
        SupportReport log=new SupportReport();SupportReport.Session s=new SupportReport.Session();s.profile=RadioProfile.MESHCORE;s.phase=SupportReport.phase("Ready");s.ready=true;s.connected=true;s.mtu=176;s.protocol=14;s.firmware="v1.18.0-private-name";
        for(int i=0;i<250;i++)log.record(RadioProfile.MESHCORE,SupportReport.Event.RX_CODE,i,1000L*i);
        String report=log.render("0.4.0",35,"Samsung SM-S947U",Arrays.asList(s));verify(report.contains("App: 0.4.0")&&report.contains("Firmware: 1.18.0"),"Version metadata is exported without arbitrary firmware suffixes");verify(!report.contains("private-name"),"Firmware suffix cannot leak a name");verify(report.contains("MTU: 176")&&report.contains("Companion protocol: 14"),"Diagnostic retains useful transport/protocol fields");verify(!report.contains("code=0\n")&&report.contains("code=249"),"Diagnostic event retention is bounded to the newest 200 events");
        verify(SupportReport.phase("secret status alice@example.com")==0,"Unknown phase text is never exported");verify(SupportReport.version("192.168.1.4").equals("unknown"),"IP address cannot masquerade as firmware version");verify(SupportReport.device("AA:BB:CC:DD:EE:FF alice@example.com 192.168.1.4 0123456789abcdef0123456789abcdef").equals("[redacted] [redacted] [redacted] [redacted]"),"Device label redacts common identifiers and keys");
        log.record(RadioProfile.MESHCORE,SupportReport.Event.TRANSPORT_ERROR,147,300000);report=log.render("0.4.0",29,"Phone",Arrays.asList(s));verify(report.contains("TRANSPORT_ERROR code=147"),"GATT error codes remain useful without raw error text");verify(report.length()<20000,"Diagnostic stays small enough to save or share");
    }
    public static void main(String[] args){assertions=0;clock=100;links();channels();announcements();contacts();diagnostic();System.out.println("MeshCore user features: "+assertions+" checks passed");}
}
